onClick:
{{
  (async function() {
    let pageSource = appsmith.store.page_precedente;
    const idSource = appsmith.store.id_precedent;

    // Si vide ou si le nom n'a pas l'émoji
    if (!pageSource || pageSource === 'Détail Article' || pageSource === 'Stock Global') {
      pageSource = '📦 Stock Global';
    }

    if (idSource) {
      await navigateTo(pageSource, { id: idSource });
    } else {
      await navigateTo(pageSource);
    }
  })()
}}
